arguments.content:
//! Replay-only delegation-cost benchmark (ticket `10d21210`).
//!
//! Loads the two checked-in baseline sessions from
//! `.benchmark/10d21210/baseline/sessions/` and asserts that
//! `compute_delegation_cost_report` reproduces the checked-in
//! `delegation_cost_report.json` byte-for-byte (after JSON value
//! normalization). This is the AC6 proof: the harness is deterministic by
//! construction (replay, not a live run), so re-running against the
//! unchanged repo reproduces the baseline metrics exactly — zero spread.
//!
//! See `.benchmark/10d21210/README.md` for the scenario definition, metric
//! set, thresholds, and the documented replay-only limitation.

use std::collections::BTreeMap;
use std::path::PathBuf;

use session_api::{SessionAuditSelector, SessionStoreConfig};

const BASELINE_SESSION_IDS: &[&str] = &[
    "3e9bc20b-4fe8-4996-ae7f-7be32525e429",
    "41966513-a8fa-4b44-98fa-9c57f0437cc0",
];

fn benchmark_root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../../.benchmark/10d21210/baseline")
}

fn checked_in_report_path() -> PathBuf {
    benchmark_root().join("delegation_cost_report.json")
}

#[test]
fn replay_reproduces_checked_in_baseline_report_exactly() {
    let root = benchmark_root();
    assert!(
        root.join("sessions").is_dir(),
        "expected checked-in baseline session fixtures at {}",
        root.display()
    );

    let store = SessionStoreConfig::new(root.clone(), "default");

    let mut computed: BTreeMap<String, serde_json::Value> = BTreeMap::new();
    for session_id in BASELINE_SESSION_IDS {
        let report = store
            .delegation_cost_report(SessionAuditSelector::SessionId((*session_id).to_string()))
            .unwrap_or_else(|err| {
                panic!("failed to compute delegation cost report for {session_id}: {err}")
            });
        let value = serde_json::to_value(&report).expect("report serializes to JSON");
        computed.insert((*session_id).to_string(), value);
    }

    let checked_in_raw = std::fs::read_to_string(checked_in_report_path()).unwrap_or_else(|err| {
        panic!(
            "failed to read checked-in baseline report at {}: {err}",
            checked_in_report_path().display()
        )
    });
    let checked_in: BTreeMap<String, serde_json::Value> =
        serde_json::from_str(&checked_in_raw).expect("checked-in report is valid JSON");

    pretty_assertions::assert_eq!(
        computed, checked_in,
        "replay of the checked-in baseline sessions did not reproduce the checked-in \
         delegation_cost_report.json exactly; the harness is replay-only and must be \
         byte-identical on every run over an unchanged repo"
    );
}

